```verilog
module onebit_fulladd(A, B, CI, Sum, Cout);   //模块名称和端口名
  input A, B, CI;                             //输入
  output Sum, Cout;                           //输出
  wire Sum_temp, C_1, C_2, C_3;               //定义模块内部的连接线
  xor                                         //用 2 个异或门 XOR1, XOR2
    XOR1(Sum_temp, A, B);
    XOR2(Sum, Sum_temp, CI);
  and                                         //用 3 个与门 AND1, AND2, AND3
    AND3(C_3, A, B);
    AND2(C_2, B, CI);
    AND1(C_1, A, CI);
  or                                          //用 1 个或门
    OR1(Cout, C_1, C_2, C_3);
endmodule                                     //结束
```

