该设计是由 8 个状态组成的循环，每个状态有相应的输出，采用 Moore 型状态机进行设计，可用两段式 Verilog HDL 描述成两个模块：模块一为状态机模块（clocked always 块，按 S0→S1→…→S7→S0 转换），模块二为输出模块（组合 always 块，由 state 译出 reg_out）。状态编码取 S0=3'b000、S1=3'b100、S2=3'b010、S3=3'b001、S4=3'b111、S5=3'b001、S6=3'b010、S7=3'b100，输出 {R,Y,G}=reg_out。代码如下：

```verilog
//8-State Moore state machine
reg[2:0] reg_out;            //output reg
reg[2:0] state;              //reg state = {Q2,Q1,Q0}
parameter S0=0,S1=1,S2=2,S3=3,S4=4,S5=5,S6=6,S7=7;

always@(posedge CLK_c or negedge RESET)
  if(!RESET)
    state<=S0;
    S1: state<=S2;
    S2: state<=S3;
    S3: state<=S4;
    S4: state<=S5;
    S5: state<=S6;
    S6: state<=S7;
    S7: state<=S0;
    endcase

//模块二：输出模块
//State machine output
always@(state)
begin
  case(state)
    S0: reg_out=3'b000;
    S1: reg_out=3'b100;
    S2: reg_out=3'b010;
    S3: reg_out=3'b001;
    S4: reg_out=3'b111;
    S5: reg_out=3'b001;
    S6: reg_out=3'b010;
    S7: reg_out=3'b100;
  endcase
end

//Output
always@(reg_out)
begin
  {R,Y,G}=reg_out;
end
endmodule
```

题 4.6 所设计的控制两台水泵的电路为 $S=A+B'C$、$L=B$，用 Verilog HDL 的结构描述如下（等效门级电路如图 P4.33 所示）：

```verilog
module control(A, B, C, L, S);
  input A, B, C;
  output L, S;
  wire Bnot, T;
  not  G1(Bnot, B);
  and  G2(T, Bnot, C);
  or   G3(S, A, T);
  buf  G4(L, B);
endmodule
```

4 选 1 数据选择器的输出为
$$out=\overline{sel_1}\,\overline{sel_0}\,data_0+\overline{sel_1}\,sel_0\,data_1+sel_1\overline{sel_0}\,data_2+sel_1sel_0\,data_3$$
功能表如图 P4.34 所示，Verilog HDL 描述为：

```verilog
module mux_4_to_1(data, out, outnot, sel);
  input  [3:0] data;
  input  [1:0] sel;
  output out, outnot;
  reg out;
  always @ (data or sel)
  begin
    case (sel)
      2'b00: out = data[0];
      2'b01: out = data[1];
      2'b10: out = data[2];
      2'b11: out = data[3];
    endcase
  end
  assign outnot = ~out;
endmodule
```

每位和与进位为
$$S_i=A_i\oplus B_i\oplus C_i\quad(i=0\sim3,\ C_0=CI)$$
$$C_1=A_0B_0+(A_0+B_0)CI$$
$$C_2=A_1B_1+(A_1+B_1)C_1$$
$$C_3=A_2B_2+(A_2+B_2)C_2$$
$$CO=C_4=A_3B_3+(A_3+B_3)C_3$$
各位进位都由 $A、B、CI$ 直接算出，与求和并行。Verilog HDL 用结构化描述：顶层 `adder_4bit` 调用 4 个 1 位全加器模块 `adder_1bit`（只算本位和）与 4 个进位模块 `Carry1`~`Carry4`：

```verilog
module adder_4bit(A, B, S, CI, CO);
  input CI;
  input  [3:0] A, B;
  output CO;
  output [3:0] S;
  wire C1, C2, C3;
  adder_1bit m0(S[0], A[0], B[0], CI);
  adder_1bit m1(S[1], A[1], B[1], C1);
  adder_1bit m2(S[2], A[2], B[2], C2);
  adder_1bit m3(S[3], A[3], B[3], C3);
  Carry1 m4(A[0], B[0], CI, C1);
  Carry2 m5(A[0], B[0], A[1], B[1], CI, C2);
  Carry3 m6(A[0], B[0], A[1], B[1], A[2], B[2], CI, C3);
  Carry4 m7(A[0], B[0], A[1], B[1], A[2], B[2], A[3], B[3], CI, CO);
endmodule
```

其中 `adder_1bit` 为 `xor g1(d,a,b); xor g2(sum,d,c);`；`Carry1`~`Carry4` 依次用 `assign C1=(A0&&B0)||((A0^B0)&&CI);` 等直接求出 $C_1\sim C_3$ 与 $CO$。

